 1 │ //! Shared helper for the Lifecycle-gate integration tests: builds a `SupervisorConfig`
 2 │ //! pointing at a fresh copy of the `fake-tsc` binary inside a `node_modules/typescript/
 3 │ //! bin/` layout, so `check_version`'s `package.json` lookup finds a real, matching
 4 │ //! version rather than needing every test to fake that out itself.
 5 │ //!
 6 │ //! Each `tests/*.rs` file compiles this module separately as its own crate, so a
 7 │ //! helper unused by one particular test binary is expected, not a real dead-code
 8 │ //! finding — hence the blanket allow below.
 9 │ #![allow(dead_code)]
10 │ 
11 │ use camino::Utf8PathBuf;
12 │ use oxc_react_docgen_tsc_client::SupervisorConfig;
13 │ 
14 │ pub const PINNED_VERSION: &str = "7.1.0-test";
15 │ 
16 │ /// Returns the temp dir (kept alive for the caller's test duration) and a config ready
17 │ /// to `Supervisor::spawn`, with `FAKE_TSC_SCENARIO` set to `scenario`.
18 │ pub fn spawn_fake(scenario: &str) -> (tempfile::TempDir, SupervisorConfig) {
19 │     let dir = tempfile::tempdir().expect("create temp dir for fake-tsc layout");
20 │     let (tsc_path, cwd) = layout_with_version(&dir, PINNED_VERSION);
21 │     let mut config = SupervisorConfig::new(tsc_path, cwd, &[PINNED_VERSION]);
22 │     config.extra_env.push(("FAKE_TSC_SCENARIO".to_string(), scenario.to_string()));
23 │     (dir, config)
24 │ }
25 │ 
26 │ /// Builds the `node_modules/typescript/{package.json,bin/tsc}` layout with the given
27 │ /// version string and a copy of the real `fake-tsc` binary at `bin/tsc`. Returns
28 │ /// `(tsc_path, cwd)`.
29 │ pub fn layout_with_version(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
30 │     let typescript_dir = dir.path().join("node_modules").join("typescript");
31 │     let bin_dir = typescript_dir.join("bin");
32 │     std::fs::create_dir_all(&bin_dir).expect("create node_modules/typescript/bin");
33 │     std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
34 │         .expect("write package.json");
35 │ 
36 │     let fake_tsc_src = std::path::PathBuf::from(env!("CARGO_BIN_EXE_fake-tsc"));
37 │     let tsc_dest = bin_dir.join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
38 │     std::fs::copy(&fake_tsc_src, &tsc_dest).expect("copy fake-tsc binary into place");
39 │ 
40 │     (
41 │         Utf8PathBuf::from_path_buf(tsc_dest).expect("temp path is UTF-8"),
42 │         Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
43 │     )
44 │ }
45 │ 
46 │ /// Same layout, but without ever placing a binary at `bin/tsc` — for the missing-binary
47 │ /// case.
48 │ pub fn layout_without_binary(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
49 │     let typescript_dir = dir.path().join("node_modules").join("typescript");
50 │     std::fs::create_dir_all(&typescript_dir).expect("create node_modules/typescript");
51 │     std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
52 │         .expect("write package.json");
53 │     let tsc_path = typescript_dir.join("bin").join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
54 │     (
55 │         Utf8PathBuf::from_path_buf(tsc_path).expect("temp path is UTF-8"),
56 │         Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
57 │     )
58 │ }
 1 │ //! Manual smoke check against the real `typescript@next` nightly — not a `cargo test`
 2 │ //! (CI has no reason to depend on an unstable nightly build), but a one-off run to
 3 │ //! confirm the fake-tsc harness's assumptions about wire behavior (framing, exit
 4 │ //! codes) still match reality. Run from the repo root:
 5 │ //!
 6 │ //! ```sh
 7 │ //! cargo run -p oxc-react-docgen-tsc-client --example smoke_real_tsc
 8 │ //! ```
 9 │ //!
10 │ //! Requires `apps/validate`'s `typescript-next` dependency to be installed (`pnpm
11 │ //! install` from the repo root) — see docs/type-checker-integration.md.
12 │ 
13 │ use std::time::Duration;
14 │ 
15 │ use camino::Utf8PathBuf;
16 │ use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig};
17 │ 
18 │ #[tokio::main]
19 │ async fn main() {
20 │     // Assumes invocation from the repo root, per this file's doc comment.
21 │     let repo_root = Utf8PathBuf::from_path_buf(std::env::current_dir().expect("cwd")).expect("repo root is UTF-8");
22 │ 
23 │     let tsc_path = repo_root.join("apps/validate/node_modules/typescript-next/bin/tsc");
24 │     let package_json_path = repo_root.join("apps/validate/node_modules/typescript-next/package.json");
25 │     let version = std::fs::read_to_string(&package_json_path)
26 │         .ok()
27 │         .and_then(|contents| serde_json::from_str::<serde_json::Value>(&contents).ok())
28 │         .and_then(|value| value.get("version").and_then(|v| v.as_str()).map(str::to_string))
29 │         .unwrap_or_else(|| panic!("could not read version from {package_json_path}"));
30 │ 
31 │     println!("Spawning {tsc_path} (version {version})...");
32 │ 
33 │     // Leaked to get a `&'static str` cheaply for this one-off binary — not a pattern
34 │     // to repeat in real caller code, which knows its pinned versions at compile time.
35 │     let expected: &'static str = Box::leak(version.into_boxed_str());
36 │     let expected: &'static [&'static str] = Box::leak(vec![expected].into_boxed_slice());
37 │     let mut config = SupervisorConfig::new(tsc_path, repo_root, expected);
38 │     config.handshake_timeout = Duration::from_secs(30); // generous for a cold nightly spawn
39 │ 
40 │     let mut supervisor = Supervisor::spawn(config).await.expect("spawn real tsc");
41 │     println!("Spawned. Sending `initialize`...");
42 │ 
43 │     let response = supervisor
44 │         .request("initialize", serde_json::json!(null), Duration::from_secs(10))
45 │         .await
46 │         .expect("initialize request");
47 │     println!("Response (seq {}): {}", response.seq, response.value);
48 │ 
49 │     supervisor.shutdown().await.expect("shutdown");
50 │     println!("Shut down cleanly.");
51 │ }

