use std::time::{Duration, Instant};

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig};

fn config() -> SupervisorConfig {
    let repo_root = Utf8PathBuf::from_path_buf(std::env::current_dir().unwrap()).unwrap();
    let tsc_path = repo_root.join("apps/validate/node_modules/typescript-next/bin/tsc");
    SupervisorConfig::new(tsc_path, repo_root, &["7.1.0-dev.20260926.1"])
}

fn ps(label: &str) {
    let out = std::process::Command::new("sh")
        .arg("-c")
        .arg(format!("ps -o pid,ppid,stat,comm -g $(ps -o pgid= -p {}) | grep -v -E 'ps|sh|grep'", std::process::id()))
        .output()
        .unwrap();
    println!("[{label}] ps:\n{}", String::from_utf8_lossy(&out.stdout));
}

#[tokio::main]
async fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();

    let mut sup = Supervisor::spawn(config()).await.unwrap();
    let r = sup.request("initialize", serde_json::json!(null), Duration::from_secs(10)).await.unwrap();
    println!("init seq {}", r.seq);
    ps("after init");

    match mode.as_str() {
        "dropped" => {
            let t = Instant::now();
            sup.shutdown().await.unwrap();
            println!("shutdown (no clones held): {:?}", t.elapsed());
        }
        "held" => {
            let held = sup.client();
            let t = Instant::now();
            sup.shutdown().await.unwrap();
            println!("shutdown (clone held): {:?}", t.elapsed());
            ps("after shutdown, clone held");
            let r = held.request("initialize", serde_json::json!(null), Duration::from_secs(3)).await;
            println!("request on held clone after shutdown: {:?}", r.map(|x| x.value));
        }
        "pending" => {
            // A clone with an in-flight request that tsc won't answer quickly: use a bogus
            // method? It'd error fast. Instead issue a request and shutdown concurrently.
            let held = sup.client();
            let task = tokio::spawn(async move {
                let t = Instant::now();
                // A request with a long deadline, fired right before shutdown.
                let r = held.request("initialize", serde_json::json!(null), Duration::from_secs(30)).await;
                (t.elapsed(), r.map(|x| x.value))
            });
            tokio::task::yield_now().await;
            let t = Instant::now();
            sup.shutdown().await.unwrap();
            println!("shutdown with pending clone request: {:?}", t.elapsed());
            println!("pending clone result: {:?}", task.await.unwrap());
        }
        "cancel" => {
            let held = sup.client();
            // Cancel shutdown after abort()+drop but before the child exits (the held clone
            // keeps stdin open so the child can't exit on EOF).
            let r = tokio::time::timeout(Duration::from_millis(300), sup.shutdown()).await;
            println!("shutdown cancelled: {}", r.is_err());
            tokio::time::sleep(Duration::from_millis(300)).await;
            ps("after cancelled shutdown (child dropped)");
            drop(held);
            tokio::time::sleep(Duration::from_millis(500)).await;
            ps("after dropping held clone");
        }
        _ => println!("mode?"),
    }
}

