mod common;

use std::time::{Duration, Instant};

use oxc_react_docgen_tsc_client::{Supervisor, SupervisorConfig};

#[tokio::test]
async fn adv_pending_clone_request_during_shutdown() {
    let (_dir, config) = common::spawn_fake("never_respond");
    let supervisor = Supervisor::spawn(config).await.unwrap();
    let clone = supervisor.client();
    let task = tokio::spawn(async move {
        let t = Instant::now();
        let r = clone.request("m", serde_json::json!(null), Duration::from_secs(8)).await;
        (t.elapsed(), r.map(|x| x.value))
    });
    tokio::time::sleep(Duration::from_millis(100)).await;
    let t = Instant::now();
    supervisor.shutdown().await.unwrap();
    eprintln!("ADV1 shutdown elapsed {:?}", t.elapsed());
    eprintln!("ADV1 pending result {:?}", task.await.unwrap());
}

#[tokio::test]
async fn adv_shutdown_slow_exits_on_eof_not_force_kill() {
    let (_dir, config) = common::spawn_fake("shutdown_slow:30000");
    let supervisor = Supervisor::spawn(config).await.unwrap();
    let t = Instant::now();
    supervisor.shutdown().await.unwrap();
    eprintln!("ADV2 shutdown_slow:30000 no clone elapsed {:?}", t.elapsed());

    let (_dir, config) = common::spawn_fake("shutdown_slow:30000");
    let supervisor = Supervisor::spawn(config).await.unwrap();
    let _held = supervisor.client();
    let t = Instant::now();
    supervisor.shutdown().await.unwrap();
    eprintln!("ADV2 shutdown_slow:30000 clone held elapsed {:?}", t.elapsed());
}

#[tokio::test]
async fn adv_stderr_non_utf8_stops_drain() {
    let dir = tempfile::tempdir().unwrap();
    let (tsc_path, cwd) = common::layout_with_version(&dir, common::PINNED_VERSION);
    // Replace the binary with a script: one non-UTF-8 stderr line, then keep writing stderr.
    std::fs::remove_file(&tsc_path).unwrap();
    std::fs::write(
        &tsc_path,
        "#!/bin/sh\nprintf 'ok line\\n' >&2\nprintf '\\377\\376 bad\\n' >&2\nsleep 0.3\ni=0\nwhile [ $i -lt 50 ]; do printf 'later line %s\\n' $i >&2 || exit 77; i=$((i+1)); sleep 0.02; done\nexec cat >/dev/null\n",
    )
    .unwrap();
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(&tsc_path, std::fs::Permissions::from_mode(0o755)).unwrap();
    let config = SupervisorConfig::new(tsc_path, cwd, &[common::PINNED_VERSION]);
    let supervisor = Supervisor::spawn(config).await.unwrap();
    tokio::time::sleep(Duration::from_millis(2000)).await;
    eprintln!("ADV5 is_alive after non-utf8 stderr + later writes: {}", supervisor.is_alive());
    let t = Instant::now();
    supervisor.shutdown().await.unwrap();
    eprintln!("ADV5 shutdown elapsed {:?}", t.elapsed());
}

